const getResolveUrl = (args: any[]): string => {
    const result = args.join(', ');
    return getResolveUrl(result);
}; 

const escapeId = (str: string): string => {
    return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
};

const partialEncodeURIPath = (path: string): string => {
    return path.replace(/%/g, '%25').replace(/&/g, '%26').replace(/=/g, '%3D').replace(/~/g, '%7E');
};

const rewrite = (relativePath: string, umd: boolean = false): string => {
    const encodedPath = partialEncodeURIPath(relativePath);
    const escapedPath = escapeId(encodedPath);

    let baseUri = '';
    if (umd) {
        baseUri = `typeof document === 'undefined' ? location.href : ` + 
                  `document.currentScript && document.currentScript.src || document.baseURI`;
    }

    const finalArgs = [`'${escapedPath}'`, ` ${baseUri ? ` ${baseUri}` : ''}`];

    return getResolveUrl(finalArgs);
};

