((prop) => {
            /**
             * For the root selector `& { ... }`, allow limited inherited
             * styles to not be namespaced.
             * These won't do anything to the `<svg>`, but will be inherited by
             * children with a lower specificity than SVG presentation attributes.
             */
            let shouldKeepUnnamespaced = false;
            if (
              prop === namespace &&
              Array.isArray(element.children)
            ) {
              let allDecl = true;
              for (let i = 0; i < element.children.length; i++) {
                const child = element.children[i];
                if (child.type !== 'decl') {
                  allDecl = false;
                  break;
                }
                const allowedProps = new Set<typeof child.props>(['font-family', 'font-size', 'fill']);
                if (!allowedProps.has(child.props)) {
                  allDecl = false;
                  break;
                }
              }
              shouldKeepUnnamespaced = allDecl;
            }

            if (shouldKeepUnnamespaced) {
              return prop;
            }

            let alreadyNamespaced = false;
            const startsWithSpace = prop.startsWith(`${namespace} `);
            const startsWithGreater = prop.startsWith(`${namespace}>`);
            const isNotCombinator = !prop.startsWith(`${namespace} ||`);

            alreadyNamespaced = (startsWithSpace || startsWithGreater) && isNotCombinator;

            if (!alreadyNamespaced) {
              return `${namespace} ${prop}`;
            }
            return prop;
          })

