async metadataHandler(req, res) {
    let data;
    try {
        const config = Config.get(req.params.appId);
        const { filesController } = config;
        const { filename } = req.params;
        data = await filesController.getMetadata(filename);
    } catch (e) {
        // On error, data remains undefined, but we proceed to the fallback response.
    } finally {
        res.status(200);
        if (data !== undefined) {
             res.json(data);
        } else {
             res.json({});
        }
    }
  }
